import{_ as t,o as a,c as h,a3 as o}from"./chunks/framework.DX_KL3e0.js";const i="/help/screenshots/dashboard/tong-quan.png",m=JSON.parse('{"title":"Dashboard (Trang chủ)","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/dashboard.md","filePath":"chuc-nang/dashboard.md","lastUpdated":1781595364000}'),g={name:"chuc-nang/dashboard.md"};function r(s,n,c,d,l,u){return a(),h("div",null,[...n[0]||(n[0]=[o('<h1 id="dashboard-trang-chu" tabindex="-1">Dashboard (Trang chủ) <a class="header-anchor" href="#dashboard-trang-chu" aria-label="Permalink to &quot;Dashboard (Trang chủ)&quot;">​</a></h1><p>Dashboard là màn hình đầu tiên sau khi đăng nhập, cung cấp tổng quan nhanh về công việc và số liệu liên quan đến bạn. <strong>Giao diện Dashboard thay đổi theo vai trò</strong> của tài khoản.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/dashboard</code> (logo và menu <em>Dashboard</em> đều dẫn về đây).</li><li><strong>Ai dùng được:</strong> Mọi người dùng — nhưng nội dung khác nhau theo vai trò.</li><li><strong>Đặc điểm:</strong> Số liệu đồng bộ thời gian thực; nhấn vào thẻ chỉ số để mở module tương ứng.</li></ul></div><h2 id="giao-dien-theo-vai-tro" tabindex="-1">Giao diện theo vai trò <a class="header-anchor" href="#giao-dien-theo-vai-tro" aria-label="Permalink to &quot;Giao diện theo vai trò&quot;">​</a></h2><p><img src="'+i+'" alt="Trung Tâm Điều Hành"></p><p>Hệ thống hiển thị một trong ba dạng Dashboard:</p><table tabindex="0"><thead><tr><th>Vai trò</th><th>Dashboard</th><th>Trọng tâm</th></tr></thead><tbody><tr><td><strong>Super Admin / Admin</strong></td><td>Trung Tâm Điều Hành</td><td>Tổng quan toàn hệ thống</td></tr><tr><td><strong>Quản lý (manager)</strong></td><td>Dashboard đội ngũ</td><td>Số liệu nhân viên cấp dưới</td></tr><tr><td><strong>Người dùng (user)</strong></td><td>Dashboard cá nhân</td><td>Công việc và nhiệm vụ của riêng bạn</td></tr></tbody></table><h2 id="dashboard-super-admin-admin-—-trung-tam-đieu-hanh" tabindex="-1">Dashboard Super Admin / Admin — &quot;Trung Tâm Điều Hành&quot; <a class="header-anchor" href="#dashboard-super-admin-admin-—-trung-tam-đieu-hanh" aria-label="Permalink to &quot;Dashboard Super Admin / Admin — &quot;Trung Tâm Điều Hành&quot;&quot;">​</a></h2><p>Hiển thị tổng quan toàn hệ thống, có nhãn <strong>&quot;Đồng bộ thời gian thực&quot;</strong>.</p><ul><li><strong>Dải KPI</strong> (đầu trang): các thẻ chỉ số đa lĩnh vực, mỗi thẻ là một cổng nhảy vào module: <ul><li><strong>Tổng Tài Sản</strong> — tổng tài sản và số cảnh báo sắp hết hạn → mở Quản lý Tài sản.</li><li><strong>Nhân Sự</strong> — số nhân sự đang làm việc → mở Nguồn Nhân Lực.</li><li>Ticket đang mở, Công việc đang mở, Yêu cầu chờ duyệt, Phòng họp chờ, Tuyển dụng chờ…</li></ul></li><li><strong>Cột chính (2/3):</strong><ul><li><strong>Việc cần xử lý</strong> (Action Items).</li><li><strong>Phân tích nhân sự</strong> (HR Insights) và xu hướng.</li></ul></li><li><strong>Cột phải (1/3):</strong> bảng tin gồm <strong>Thông báo gần đây</strong> và <strong>Văn bản gần đây</strong>.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Nhấn vào bất kỳ thẻ chỉ số nào để đi thẳng vào module liên quan.</p></div><h2 id="dashboard-quan-ly-manager-—-đoi-ngu" tabindex="-1">Dashboard Quản lý (manager) — đội ngũ <a class="header-anchor" href="#dashboard-quan-ly-manager-—-đoi-ngu" aria-label="Permalink to &quot;Dashboard Quản lý (manager) — đội ngũ&quot;">​</a></h2><p>Tập trung vào <strong>nhân viên cấp dưới</strong> của bạn (theo cấu trúc quản lý). Lời chào &quot;Xin chào, [tên]&quot;.</p><ul><li><strong>Dải KPI đội:</strong><ul><li><strong>Quân số nhóm</strong> — tổng nhân viên trong nhóm.</li><li><strong>Chờ tôi duyệt</strong> — số đơn cấp dưới chờ bạn duyệt → mở Duyệt Yêu Cầu.</li><li><strong>Ticket nhóm mở</strong> · <strong>Công việc nhóm</strong>.</li></ul></li><li><strong>Cần Tôi Duyệt:</strong> liệt kê đơn theo loại (nghỉ phép, tăng ca, bù công/điều chỉnh); nhấn để vào màn duyệt.</li><li><strong>Đội Ngũ Hôm Nay:</strong> ticket nhóm hôm nay, task đến hạn hôm nay, số người nghỉ phép, số vắng/chưa chấm công.</li><li><strong>Việc của tôi:</strong> công việc và ticket cá nhân của bạn.</li><li><strong>Cột phải:</strong> Thông báo và Văn bản gần đây.</li></ul><h2 id="dashboard-nguoi-dung-user-—-ca-nhan" tabindex="-1">Dashboard Người dùng (user) — cá nhân <a class="header-anchor" href="#dashboard-nguoi-dung-user-—-ca-nhan" aria-label="Permalink to &quot;Dashboard Người dùng (user) — cá nhân&quot;">​</a></h2><p>Tập trung vào công việc của chính bạn. Lời chào &quot;Xin chào, [tên]&quot;.</p><ul><li><strong>Thao tác nhanh</strong> (đầu trang): các nút tắt — <strong>Đầu Mối Liên Hệ</strong>, <strong>Tạo ticket</strong>, <strong>Đặt phòng</strong>, <strong>Xin nghỉ phép</strong>.</li><li><strong>Cột chính:</strong><ul><li><strong>Cần xử lý:</strong> số ticket đang mở, số công việc chưa hoàn thành, số phòng họp đang chờ duyệt.</li><li><strong>Việc của tôi:</strong> danh sách ticket và công việc được giao cho bạn.</li><li><strong>Phòng họp của tôi:</strong> các lượt đặt phòng bạn đã tạo.</li></ul></li><li><strong>Cột phải:</strong> Thông báo, Văn bản gần đây, <strong>Thống kê</strong> cá nhân và <strong>Hoạt động gần đây</strong>.</li></ul><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Vì sao Dashboard của tôi khác đồng nghiệp?</strong> Nội dung Dashboard tùy theo vai trò (Super Admin/Admin, Quản lý, Người dùng). Đây là thiết kế nhằm hiển thị đúng thông tin cần thiết cho từng nhóm.</p><p><strong>Số liệu có cập nhật tức thời không?</strong> Có. Dashboard đồng bộ theo thời gian thực; các con số tự cập nhật khi dữ liệu thay đổi.</p><p><strong>Nhấn vào thẻ chỉ số thì sao?</strong> Hệ thống mở module tương ứng (ví dụ thẻ Tổng Tài Sản dẫn tới Quản lý Tài sản).</p><hr><p><em>Liên quan:</em> <a href="/help/bat-dau/giao-dien-chung.html">Giao diện chung</a> · <a href="/help/chuc-nang/tai-san.html">Quản lý Tài sản</a> · <a href="/help/chuc-nang/cong-viec.html">Công Việc</a></p>',23)])])}const p=t(g,[["render",r]]);export{m as __pageData,p as default};
